def request_response(func: Callable[[Request], Awaitable[Response] | Response]) -> ASGIApp:
    """
    Takes a function or coroutine `func(request) -> response`,
    and returns an ASGI application.
    """
    f: Callable[[Request], Awaitable[Response]] = func if is_async_callable(func) else functools.partial(run_in_threadpool, func)

    async def app(scope: Scope, receive: Receive, send: Send) -> None:
        request = Request(scope, receive, send)

        async def app(scope: Scope, receive: Receive, send: Send) -> None:
            response_awaited = False
            async with AsyncExitStack() as request_stack:
                scope['fastapi_inner_astack'] = request_stack
                async with AsyncExitStack() as function_stack:
                    scope['fastapi_function_astack'] = function_stack
                    response = await f(request)
                await response(scope, receive, send)
                response_awaited = True
            if not response_awaited:
                raise FastAPIError("Response not awaited. There's a high chance that the application code is raising an exception and a dependency with yield has a block with a bare except, or a block with except Exception, and is not raising the exception again. Read more about it in the docs: https://fastapi.tiangolo.com/tutorial/dependencies/dependencies-with-yield/#dependencies-with-yield-and-except")
        await wrap_app_handling_exceptions(app, request)(scope, receive, send)
    return app

def websocket_session(func: Callable[[WebSocket], Awaitable[None]]) -> ASGIApp:
    """
    Takes a coroutine `func(session)`, and returns an ASGI application.
    """

    async def app(scope: Scope, receive: Receive, send: Send) -> None:
        session = WebSocket(scope, receive=receive, send=send)

        async def app(scope: Scope, receive: Receive, send: Send) -> None:
            async with AsyncExitStack() as request_stack:
                scope['fastapi_inner_astack'] = request_stack
                async with AsyncExitStack() as function_stack:
                    scope['fastapi_function_astack'] = function_stack
                    await func(session)
        await wrap_app_handling_exceptions(app, session)(scope, receive, send)
    return app
_T = TypeVar('_T')

class _AsyncLiftContextManager(AbstractAsyncContextManager[_T]):
    """
    Wraps a synchronous context manager to make it async.

    This is vendored from Starlette to avoid importing private symbols.
    """

    def __init__(self, cm: AbstractContextManager[_T]) -> None:
        self._cm = cm

    async def __aenter__(self) -> _T:
        return self._cm.__enter__()

    async def __aexit__(self, exc_type: type[BaseException] | None, exc_value: BaseException | None, traceback: types.TracebackType | None) -> bool | None:
        return self._cm.__exit__(exc_type, exc_value, traceback)

def _wrap_gen_lifespan_context(lifespan_context: Callable[[Any], Generator[Any, Any, Any]]) -> Callable[[Any], AbstractAsyncContextManager[Any]]:
    """
    Wrap a generator-based lifespan context into an async context manager.

    This is vendored from Starlette to avoid importing private symbols.
    """
    cmgr = contextlib.contextmanager(lifespan_context)

    @functools.wraps(cmgr)
    def wrapper(app: Any) -> _AsyncLiftContextManager[Any]:
        return _AsyncLiftContextManager(cmgr(app))
    return wrapper

def _merge_lifespan_context(original_context: Lifespan[Any], nested_context: Lifespan[Any]) -> Lifespan[Any]:

    @asynccontextmanager
    async def merged_lifespan(app: AppType) -> AsyncIterator[Mapping[str, Any] | None]:
        async with original_context(app) as maybe_original_state:
            async with nested_context(app) as maybe_nested_state:
                if maybe_nested_state is None and maybe_original_state is None:
                    yield None
                else:
                    yield {**(maybe_nested_state or {}), **(maybe_original_state or {})}
    return merged_lifespan

class _DefaultLifespan:
    """
    Default lifespan context manager that runs on_startup and on_shutdown handlers.

    This is a copy of the Starlette _DefaultLifespan class that was removed
    in Starlette. FastAPI keeps it to maintain backward compatibility with
    on_startup and on_shutdown event handlers.

    Ref: https://github.com/Kludex/starlette/pull/3117
    """

    def __init__(self, router: 'APIRouter') -> None:
        self._router = router

    async def __aenter__(self) -> None:
        await self._router._startup()

    async def __aexit__(self, *exc_info: object) -> None:
        await self._router._shutdown()

    def __call__(self: _T, app: object) -> _T:
        return self
_endpoint_context_cache: dict[int, EndpointContext] = {}

def _extract_endpoint_context(func: Any) -> EndpointContext:
    """Extract endpoint context with caching to avoid repeated file I/O."""
    func_id = id(func)
    if func_id in _endpoint_context_cache:
        return _endpoint_context_cache[func_id]
    try:
        ctx: EndpointContext = {}
        if (source_file := inspect.getsourcefile(func)) is not None:
            ctx['file'] = source_file
        if (line_number := inspect.getsourcelines(func)[1]) is not None:
            ctx['line'] = line_number
        if (func_name := getattr(func, '__name__', None)) is not None:
            ctx['function'] = func_name
    except Exception:
        ctx = EndpointContext()
    _endpoint_context_cache[func_id] = ctx
    return ctx

def _normalize_non_finite_floats(data: Any) -> Any:
    """Replace non-finite values in JSON-compatible data, preserving dict keys."""
    if isinstance(data, float):
        return data if math.isfinite(data) else None
    if isinstance(data, dict):
        return {key: _normalize_non_finite_floats(value) for key, value in data.items()}
    if isinstance(data, list):
        return [_normalize_non_finite_floats(value) for value in data]
    return data

async def serialize_response(*, field: ModelField | None=None, response_content: Any, include: IncEx | None=None, exclude: IncEx | None=None, by_alias: bool=True, exclude_unset: bool=False, exclude_defaults: bool=False, exclude_none: bool=False, is_coroutine: bool=True, endpoint_ctx: EndpointContext | None=None, dump_json: bool=False) -> Any:
    if field:
        if is_coroutine:
            value, errors = field.validate(response_content, {}, loc=('response',))
        else:
            value, errors = await run_in_threadpool(field.validate, response_content, {}, loc=('response',))
        if errors:
            ctx = endpoint_ctx or EndpointContext()
            raise ResponseValidationError(errors=errors, body=response_content, endpoint_ctx=ctx)
        serializer = field.serialize_json if dump_json else field.serialize
        return serializer(value, include=include, exclude=exclude, by_alias=by_alias, exclude_unset=exclude_unset, exclude_defaults=exclude_defaults, exclude_none=exclude_none)
    else:
        return jsonable_encoder(response_content)

async def run_endpoint_function(*, dependant: Dependant, values: dict[str, Any], is_coroutine: bool) -> Any:
    assert dependant.call is not None, 'dependant.call must be a function'
    if is_coroutine:
        with _operation(name='endpoint', function=dependant.call):
            return await dependant.call(**values)
    else:
        return await run_in_threadpool(_run_sync_endpoint, function=dependant.call, arguments=values)

def _build_response_args(*, status_code: int | None, solved_result: Any) -> dict[str, Any]:
    response_args: dict[str, Any] = {'background': solved_result.background_tasks}
    current_status_code = status_code if status_code else solved_result.response.status_code
    if current_status_code is not None:
        response_args['status_code'] = current_status_code
    if solved_result.response.status_code:
        response_args['status_code'] = solved_result.response.status_code
    return response_args

def get_request_handler(dependant: Dependant, body_field: ModelField | None=None, status_code: int | None=None, response_class: type[Response] | DefaultPlaceholder=Default(JSONResponse), response_field: ModelField | None=None, response_model_include: IncEx | None=None, response_model_exclude: IncEx | None=None, response_model_by_alias: bool=True, response_model_exclude_unset: bool=False, response_model_exclude_defaults: bool=False, response_model_exclude_none: bool=False, dependency_overrides_provider: Any | None=None, embed_body_fields: bool=False, strict_content_type: bool | DefaultPlaceholder=Default(True), stream_item_field: ModelField | None=None, is_json_stream: bool=False, form_limits: _FormLimits | None=None) -> Callable[[Request], Coroutine[Any, Any, Response]]:
    assert dependant.call is not None, 'dependant.call must be a function'
    is_coroutine = _is_coroutine_callable(dependant.call)
    is_body_form = body_field and isinstance(body_field.field_info, params.Form)
    if isinstance(response_class, DefaultPlaceholder):
        actual_response_class: type[Response] = response_class.value
    else:
        actual_response_class = response_class
    is_sse_stream = lenient_issubclass(actual_response_class, EventSourceResponse)
    if isinstance(strict_content_type, DefaultPlaceholder):
        actual_strict_content_type: bool = strict_content_type.value
    else:
        actual_strict_content_type = strict_content_type

    async def app(request: Request) -> Response:
        telemetry_data = get_telemetry_data()
        if telemetry_data is not None:
            telemetry_data.request = request
        response: Response | None = None
        file_stack = request.scope.get('fastapi_middleware_astack')
        assert isinstance(file_stack, AsyncExitStack), 'fastapi_middleware_astack not found in request scope'
        endpoint_ctx = _extract_endpoint_context(dependant.call) if dependant.call else EndpointContext()
        if dependant.path:
            mount_path = request.scope.get('root_path', '').rstrip('/')
            endpoint_ctx['path'] = f'{request.method} {mount_path}{dependant.path}'
        try:
            body: Any = Undefined
            if body_field:
                if is_body_form:
                    limits = _resolve_form_limits(request.scope.get(_FASTAPI_SCOPE_KEY, {}), form_limits)
                    body = await request.form(**limits)
                    file_stack.push_async_callback(body.close)
                else:
                    body_bytes = await request.body()
                    if body_bytes:
                        json_body: Any = Undefined
                        content_type_value = request.headers.get('content-type')
                        if not content_type_value:
                            if not actual_strict_content_type:
                                json_body = await request.json()
                        else:
                            message = email.message.Message()
                            message['content-type'] = content_type_value
                            if message.get_content_maintype() == 'application':
                                subtype = message.get_content_subtype()
                                if subtype == 'json' or subtype.endswith('+json'):
                                    json_body = await request.json()
                        if json_body is not Undefined:
                            body = json_body
                        else:
                            body = body_bytes
        except json.JSONDecodeError as e:
            validation_error = RequestValidationError([{'type': 'json_invalid', 'loc': ('body', e.pos), 'msg': 'JSON decode error', 'input': {}, 'ctx': {'error': e.msg}}], body=e.doc, endpoint_ctx=endpoint_ctx)
            _validation_failed(validation_error)
            raise validation_error from e
        except HTTPException:
            raise
        except Exception as e:
            if MAX_BODY_SIZE_SCOPE_KEY in request.scope and (error := get_body_limit_error(e)):
                raise error from e
            http_error = HTTPException(status_code=400, detail='There was an error parsing the body')
            raise http_error from e
        if telemetry_data is not None:
            telemetry_data.body = None if body is Undefined else body
        errors: list[Any] = []
        async_exit_stack = request.scope.get('fastapi_inner_astack')
        assert isinstance(async_exit_stack, AsyncExitStack), 'fastapi_inner_astack not found in request scope'
        with _operation(name='dependencies', function=dependant.call):
            solved_result = await solve_dependencies(request=request, dependant=dependant, body=body, dependency_overrides_provider=dependency_overrides_provider, async_exit_stack=async_exit_stack, embed_body_fields=embed_body_fields, dependency_cache={})
            if telemetry_data is not None:
                telemetry_data.values = solved_result.values
                telemetry_data.errors = solved_result.errors
        errors = solved_result.errors
        assert dependant.call
        if not errors:

            def _serialize_data(data: Any) -> bytes:
                if stream_item_field:
                    value, errors_ = stream_item_field.validate(data, {}, loc=('response',))
                    if errors_:
                        ctx = endpoint_ctx or EndpointContext()
                        raise ResponseValidationError(errors=errors_, body=data, endpoint_ctx=ctx)
                    return stream_item_field.serialize_json(value, include=response_model_include, exclude=response_model_exclude, by_alias=response_model_by_alias, exclude_unset=response_model_exclude_unset, exclude_defaults=response_model_exclude_defaults, exclude_none=response_model_exclude_none)
                else:
                    data = jsonable_encoder(data)
                    return json.dumps(_normalize_non_finite_floats(data)).encode('utf-8')
            if is_sse_stream:
                gen = dependant.call(**solved_result.values)

                def _serialize_sse_item(item: Any) -> bytes:
                    if isinstance(item, ServerSentEvent):
                        if item.raw_data is not None:
                            data_str: str | None = item.raw_data
                        elif item.data is not None:
                            if hasattr(item.data, 'model_dump_json'):
                                data_str = item.data.model_dump_json()
                            else:
                                data_str = json.dumps(_normalize_non_finite_floats(jsonable_encoder(item.data)))
                        else:
                            data_str = None
                        return format_sse_event(data_str=data_str, event=item.event, id=item.id, retry=item.retry, comment=item.comment)
                    else:
                        return format_sse_event(data_str=_serialize_data(item).decode('utf-8'))
                if _is_async_gen_callable(dependant.call):
                    sse_aiter: AsyncIterator[Any] = gen.__aiter__()
                else:
                    sse_aiter = iterate_in_threadpool(gen)

                @asynccontextmanager
                async def _sse_producer_cm() -> AsyncIterator[ObjectReceiveStream[bytes]]:
                    send_stream, receive_stream = anyio.create_memory_object_stream[bytes](max_buffer_size=1)

                    async def _producer() -> None:
                        async with send_stream:
                            async for raw_item in sse_aiter:
                                await send_stream.send(_serialize_sse_item(raw_item))
                    send_keepalive, receive_keepalive = anyio.create_memory_object_stream[bytes](max_buffer_size=1)

                    async def _keepalive_inserter() -> None:
                        """Read from the producer and forward to the output,
                        inserting keepalive comments on timeout."""
                        async with send_keepalive, receive_stream:
                            try:
                                while True:
                                    try:
                                        with anyio.fail_after(_PING_INTERVAL):
                                            data = await receive_stream.receive()
                                        await send_keepalive.send(data)
                                    except TimeoutError:
                                        await send_keepalive.send(KEEPALIVE_COMMENT)
                            except anyio.EndOfStream:
                                pass
                    async with anyio.create_task_group() as tg:
                        tg.start_soon(_producer)
                        tg.start_soon(_keepalive_inserter)
                        yield receive_keepalive
                        tg.cancel_scope.cancel()
                sse_receive_stream = await async_exit_stack.enter_async_context(_sse_producer_cm())
                async_exit_stack.push_async_callback(sse_receive_stream.aclose)

                async def _sse_with_checkpoints(stream: ObjectReceiveStream[bytes]) -> AsyncIterator[bytes]:
                    async for data in stream:
                        yield data
                        await anyio.sleep(0)
                sse_stream_content: AsyncIterator[bytes] | Iterator[bytes] = _sse_with_checkpoints(sse_receive_stream)
                response_args = _build_response_args(status_code=status_code, solved_result=solved_result)
                response = StreamingResponse(sse_stream_content, media_type='text/event-stream', **response_args)
                response.headers['Cache-Control'] = 'no-cache'
                response.headers['X-Accel-Buffering'] = 'no'
                response.headers.raw.extend(solved_result.response.headers.raw)
            elif is_json_stream:
                gen = dependant.call(**solved_result.values)

                def _serialize_item(item: Any) -> bytes:
                    return _serialize_data(item) + b'\n'
                if _is_async_gen_callable(dependant.call):

                    async def _async_stream_jsonl() -> AsyncIterator[bytes]:
                        async for item in gen:
                            yield _serialize_item(item)
                            await anyio.sleep(0)
                    jsonl_stream_content: AsyncIterator[bytes] | Iterator[bytes] = _async_stream_jsonl()
                else:

                    def _sync_stream_jsonl() -> Iterator[bytes]:
                        for item in gen:
                            yield _serialize_item(item)
                    jsonl_stream_content = _sync_stream_jsonl()
                response_args = _build_response_args(status_code=status_code, solved_result=solved_result)
                response = StreamingResponse(jsonl_stream_content, media_type='application/jsonl', **response_args)
                response.headers.raw.extend(solved_result.response.headers.raw)
            elif _is_async_gen_callable(dependant.call) or _is_gen_callable(dependant.call):
                gen = dependant.call(**solved_result.values)
                if _is_async_gen_callable(dependant.call):

                    async def _async_stream_raw(async_gen: AsyncIterator[Any]) -> AsyncIterator[Any]:
                        async for chunk in async_gen:
                            yield chunk
                            await anyio.sleep(0)
                    gen = _async_stream_raw(gen)
                response_args = _build_response_args(status_code=status_code, solved_result=solved_result)
                response = actual_response_class(content=gen, **response_args)
                response.headers.raw.extend(solved_result.response.headers.raw)
            else:
                raw_response = await run_endpoint_function(dependant=dependant, values=solved_result.values, is_coroutine=is_coroutine)
                if isinstance(raw_response, Response):
                    if raw_response.background is None:
                        raw_response.background = solved_result.background_tasks
                    response = raw_response
                else:
                    response_args = _build_response_args(status_code=status_code, solved_result=solved_result)
                    use_dump_json = response_field is not None and isinstance(response_class, DefaultPlaceholder)
                    with _operation(name='serialization', function=dependant.call):
                        content = await serialize_response(field=response_field, response_content=raw_response, include=response_model_include, exclude=response_model_exclude, by_alias=response_model_by_alias, exclude_unset=response_model_exclude_unset, exclude_defaults=response_model_exclude_defaults, exclude_none=response_model_exclude_none, is_coroutine=is_coroutine, endpoint_ctx=endpoint_ctx, dump_json=use_dump_json)
                    if use_dump_json:
                        response = Response(content=content, media_type='application/json', **response_args)
                    else:
                        response = actual_response_class(content, **response_args)
                    if not is_body_allowed_for_status_code(response.status_code):
                        response.body = b''
                    response.headers.raw.extend(solved_result.response.headers.raw)
        if errors:
            validation_error = RequestValidationError(errors, body=None if body is Undefined else body, endpoint_ctx=endpoint_ctx)
            _validation_failed(validation_error)
            raise validation_error
        assert response
        return response
    return app

def get_websocket_app(dependant: Dependant, dependency_overrides_provider: Any | None=None, embed_body_fields: bool=False) -> Callable[[WebSocket], Coroutine[Any, Any, Any]]:

    async def app(websocket: WebSocket) -> None:
        telemetry_data = get_telemetry_data()
        if telemetry_data is not None:
            telemetry_data.websocket = websocket
        endpoint_ctx = _extract_endpoint_context(dependant.call) if dependant.call else EndpointContext()
        if dependant.path:
            mount_path = websocket.scope.get('root_path', '').rstrip('/')
            endpoint_ctx['path'] = f'WS {mount_path}{dependant.path}'
        async_exit_stack = websocket.scope.get('fastapi_inner_astack')
        assert isinstance(async_exit_stack, AsyncExitStack), 'fastapi_inner_astack not found in request scope'
        with _operation(name='dependencies', function=dependant.call):
            solved_result = await solve_dependencies(request=websocket, dependant=dependant, dependency_overrides_provider=dependency_overrides_provider, async_exit_stack=async_exit_stack, embed_body_fields=embed_body_fields)
            if telemetry_data is not None:
                telemetry_data.values = solved_result.values
                telemetry_data.errors = solved_result.errors
        if solved_result.errors:
            validation_error = WebSocketRequestValidationError(solved_result.errors, endpoint_ctx=endpoint_ctx)
            _validation_failed(validation_error)
            raise validation_error
        assert dependant.call is not None, 'dependant.call must be a function'
        with _operation(name='endpoint', function=dependant.call):
            await dependant.call(**solved_result.values)
    return app

class APIWebSocketRoute(routing.WebSocketRoute):

    def __init__(self, path: str, endpoint: Callable[..., Any], *, name: str | None=None, dependencies: Sequence[params.Depends] | None=None, dependency_overrides_provider: Any | None=None) -> None:
        self.path = path
        self.endpoint = endpoint
        self.name = get_name(endpoint) if name is None else name
        self.dependencies = list(dependencies or [])
        self.path_regex, self.path_format, self.param_convertors = compile_path(path)
        self.dependant, _, self._embed_body_fields = _build_dependant_with_parameterless_dependencies(path=self.path_format, call=self.endpoint, dependencies=self.dependencies)
        self.app = websocket_session(get_websocket_app(dependant=self.dependant, dependency_overrides_provider=dependency_overrides_provider, embed_body_fields=self._embed_body_fields))

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        match, child_scope = super().matches(scope)
        if match != Match.NONE:
            child_scope['route'] = self
        return (match, child_scope)
