    if current_status_code is not None:
        response_args['status_code'] = current_status_code
    if solved_result.response.status_code:
        response_args['status_code'] = solved_result.response.status_code
    return response_args

def get_request_handler(dependant: Dependant, body_field: ModelField | None=None, status_code: int | None=None, response_class: type[Response] | DefaultPlaceholder=Default(JSONResponse), response_field: ModelField | None=None, response_model_include: IncEx | None=None, response_model_exclude: IncEx | None=None, response_model_by_alias: bool=True, response_model_exclude_unset: bool=False, response_model_exclude_defaults: bool=False, response_model_exclude_none: bool=False, dependency_overrides_provider: Any | None=None, embed_body_fields: bool=False, strict_content_type: bool | DefaultPlaceholder=Default(True), stream_item_field: ModelField | None=None, is_json_stream: bool=False, form_limits: _FormLimits | None=None) -> Callable[[Request], Coroutine[Any, Any, Response]]:
