        if telemetry_data is not None:
            telemetry_data.request = request
        response: Response | None = None
        file_stack = request.scope.get('fastapi_middleware_astack')
        assert isinstance(file_stack, AsyncExitStack), 'fastapi_middleware_astack not found in request scope'
        endpoint_ctx = _extract_endpoint_context(dependant.call) if dependant.call else EndpointContext()
        if dependant.path:
            mount_path = request.scope.get('root_path', '').rstrip('/')
            endpoint_ctx['path'] = f'{request.method} {mount_path}{dependant.path}'
        try:
            body: Any = Undefined
            if body_field:
                if is_body_form:
                    limits = _resolve_form_limits(request.scope.get(_FASTAPI_SCOPE_KEY, {}), form_limits)
                    body = await request.form(**limits)
                    file_stack.push_async_callback(body.close)
                else:
                    body_bytes = await request.body()
                    if body_bytes:
                        json_body: Any = Undefined
                        content_type_value = request.headers.get('content-type')
                        if not content_type_value:
                            if not actual_strict_content_type:
                                json_body = await request.json()
                        else:
                            message = email.message.Message()
                            message['content-type'] = content_type_value
                            if message.get_content_maintype() == 'application':
                                subtype = message.get_content_subtype()
                                if subtype == 'json' or subtype.endswith('+json'):
