_SCOPE_MISSING = object()

def _frontend_dependency_endpoint() -> None:
    pass

def _build_dependant_with_parameterless_dependencies(*, path: str, call: Callable[..., Any], dependencies: Sequence[params.Depends]) -> tuple[Dependant, list[ModelField], bool]:
    dependant = get_dependant(path=path, call=call, scope='function')
    for depends in dependencies[::-1]:
        dependant.dependencies.insert(0, get_parameterless_sub_dependant(depends=depends, path=path))
