def get_websocket_app(dependant: Dependant, dependency_overrides_provider: Any | None=None, embed_body_fields: bool=False) -> Callable[[WebSocket], Coroutine[Any, Any, Any]]:

    async def app(websocket: WebSocket) -> None:
        telemetry_data = get_telemetry_data()
        if telemetry_data is not None:
            telemetry_data.websocket = websocket
        endpoint_ctx = _extract_endpoint_context(dependant.call) if dependant.call else EndpointContext()
        if dependant.path:
            mount_path = websocket.scope.get('root_path', '').rstrip('/')
            endpoint_ctx['path'] = f'WS {mount_path}{dependant.path}'
        async_exit_stack = websocket.scope.get('fastapi_inner_astack')
        assert isinstance(async_exit_stack, AsyncExitStack), 'fastapi_inner_astack not found in request scope'
        with _operation(name='dependencies', function=dependant.call):
            solved_result = await solve_dependencies(request=websocket, dependant=dependant, dependency_overrides_provider=dependency_overrides_provider, async_exit_stack=async_exit_stack, embed_body_fields=embed_body_fields)
            if telemetry_data is not None:
                telemetry_data.values = solved_result.values
                telemetry_data.errors = solved_result.errors
        if solved_result.errors:
            validation_error = WebSocketRequestValidationError(solved_result.errors, endpoint_ctx=endpoint_ctx)
            _validation_failed(validation_error)
            raise validation_error
        assert dependant.call is not None, 'dependant.call must be a function'
        with _operation(name='endpoint', function=dependant.call):
            await dependant.call(**solved_result.values)
    return app

