_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY = 'effective_route_context'
_FASTAPI_FORM_LIMITS_KEY = 'form_limits'
_FASTAPI_FRONTEND_PATH_KEY = 'frontend_path'
