    starlette_route: BaseRoute | None = None
    app: ASGIApp | None = field(default=None, repr=False, compare=False)
    frontend_prefix: str = ''
    path: str = ''
    endpoint: Callable[..., Any] | None = None
    stream_item_type: Any | None = None
    response_model: Any = None
    summary: str | None = None
    response_description: str = 'Successful Response'
    deprecated: bool | None = None
    operation_id: str | None = None
    response_model_include: IncEx | None = None
    response_model_exclude: IncEx | None = None
    response_model_by_alias: bool = True
    response_model_exclude_unset: bool = False
    response_model_exclude_defaults: bool = False
    response_model_exclude_none: bool = False
    include_in_schema: bool = True
    response_class: type[Response] | DefaultPlaceholder = field(default_factory=lambda: Default(JSONResponse))
    dependency_overrides_provider: Any | None = None
    callbacks: list[BaseRoute] | None = None
    openapi_extra: dict[str, Any] | None = None
    generate_unique_id_function: Callable[[Any], str] | DefaultPlaceholder = field(default_factory=lambda: Default(generate_unique_id))
    strict_content_type: bool | DefaultPlaceholder = field(default_factory=lambda: Default(True))
    max_body_size: int | None = None
    tags: list[str | Enum] = field(default_factory=list)
    responses: dict[int | str, dict[str, Any]] = field(default_factory=dict)
    name: str = ''
    path_regex: Any = None
    path_format: str = ''
    param_convertors: dict[str, Any] = field(default_factory=dict)
    methods: set[str] = field(default_factory=set)
    unique_id: str = ''
    status_code: int | None = None
    response_field: ModelField | None = None
    stream_item_field: ModelField | None = None
    dependencies: list[params.Depends] = field(default_factory=list)
    description: str = ''
    response_fields: dict[int | str, ModelField] = field(default_factory=dict)
    dependant: Dependant | None = None
    _embed_body_fields: bool = False
    body_field: ModelField | None = None
    is_sse_stream: bool = False
    is_json_stream: bool = False

    @classmethod
    def from_api_route(cls, *, original_route: APIRoute, include_context: _RouterIncludeContext) -> '_EffectiveRouteContext':
        route = cast(_APIRouteLike, original_route)
        context = cls(original_route=original_route)
        _populate_api_route_state(cast(_APIRouteLike, context), include_context.path_for(original_route), route.endpoint, response_model=route.response_model, status_code=route.status_code, tags=[*include_context.tags, *route.tags], dependencies=[*include_context.dependencies, *route.dependencies], summary=route.summary, description=route.description, response_description=route.response_description, responses={**include_context.responses, **route.responses}, deprecated=route.deprecated or include_context.deprecated, methods=route.methods, operation_id=route.operation_id, response_model_include=route.response_model_include, response_model_exclude=route.response_model_exclude, response_model_by_alias=route.response_model_by_alias, response_model_exclude_unset=route.response_model_exclude_unset, response_model_exclude_defaults=route.response_model_exclude_defaults, response_model_exclude_none=route.response_model_exclude_none, include_in_schema=route.include_in_schema and include_context.include_in_schema, response_class=get_value_or_default(route.response_class, include_context.included_router.default_response_class, include_context.default_response_class), name=route.name, dependency_overrides_provider=include_context.dependency_overrides_provider, callbacks=[*include_context.callbacks, *(route.callbacks or [])], openapi_extra=route.openapi_extra, generate_unique_id_function=get_value_or_default(route.generate_unique_id_function, include_context.included_router.generate_unique_id_function, include_context.generate_unique_id_function), strict_content_type=get_value_or_default(route.strict_content_type, include_context.included_router.strict_content_type, include_context.strict_content_type), stream_item_type=route.stream_item_type, max_body_size=get_body_size_limit(route.max_body_size, include_context.max_body_size))
        token = _effective_route_context_var.set(context)
        try:
            context.app = wrap_app_with_body_limit(request_response(original_route.get_route_handler()), context.max_body_size)
        finally:
            _effective_route_context_var.reset(token)
        return context

    @classmethod
    def from_frontend_route_group(cls, *, original_route: '_FrontendRouteGroup', include_context: _RouterIncludeContext) -> '_EffectiveRouteContext':
        dependencies = [*include_context.dependencies, *original_route.dependencies]
        context = cls(original_route=original_route, frontend_prefix=include_context.prefix, dependencies=dependencies, dependency_overrides_provider=include_context.dependency_overrides_provider)
        context.dependant, _, context._embed_body_fields = _build_dependant_with_parameterless_dependencies(path='', call=_frontend_dependency_endpoint, dependencies=dependencies)
        return context

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        if isinstance(self.original_route, _FrontendRouteGroup):
            return self.original_route.matches_with_prefix(scope, self.frontend_prefix)
        if not isinstance(self.original_route, APIRoute):
            assert self.starlette_route is not None
            return self.starlette_route.matches(scope)
        if scope['type'] != 'http':
            return (Match.NONE, {})
        route_path = get_route_path(scope)
        match = self.path_regex.match(route_path)
        if not match:
            return (Match.NONE, {})
        matched_params = match.groupdict()
        for key, value in matched_params.items():
            matched_params[key] = self.param_convertors[key].convert(value)
        path_params = dict(scope.get('path_params', {}))
        path_params.update(matched_params)
        child_scope = {'endpoint': self.endpoint, 'path_params': path_params}
        methods = self.methods
        if methods and scope['method'] not in methods:
            return (Match.PARTIAL, child_scope)
        return (Match.FULL, child_scope)

    def url_path_for(self, name: str, /, **path_params: Any) -> Any:
        if not isinstance(self.original_route, APIRoute):
            assert self.starlette_route is not None
            return self.starlette_route.url_path_for(name, **path_params)
        seen_params = set(path_params.keys())
        param_convertors = self.param_convertors
        expected_params = set(param_convertors.keys())
        if name != self.name or seen_params != expected_params:
            raise routing.NoMatchFound(name, path_params)
        path, remaining_params = routing.replace_params(self.path_format, param_convertors, path_params)
        assert not remaining_params
        return URLPath(path=path, protocol='http')

@dataclass(frozen=True)
class RouteContext:
    route: BaseRoute
    _route_context: _EffectiveRouteContext | None = field(default=None, repr=False)

    @property
    def original_route(self) -> BaseRoute:
        if self._route_context is not None:
            return self._route_context.original_route
        return self.route

    @property
    def _effective_route(self) -> BaseRoute | _EffectiveRouteContext:
        if self._route_context is not None:
            if self._route_context.starlette_route is not None:
                return self._route_context.starlette_route
            return self._route_context
        return self.route

    @property
    def path(self) -> str | None:
        return getattr(self._effective_route, 'path', None)

    @property
    def path_format(self) -> str | None:
        return getattr(self._effective_route, 'path_format', None)

    @property
    def name(self) -> str | None:
        return getattr(self._effective_route, 'name', None)

    @property
    def methods(self) -> set[str] | None:
        return getattr(self._effective_route, 'methods', None)

    @property
    def endpoint(self) -> Callable[..., Any] | None:
        return getattr(self._effective_route, 'endpoint', None)

    def __getattr__(self, name: str) -> Any:
        return getattr(self._effective_route, name)

@dataclass
class _IncludedRouter(BaseRoute):
    original_router: 'APIRouter'
    include_context: _RouterIncludeContext
    _effective_routes_lock: Any = field(default_factory=threading.Lock, repr=False, compare=False)
    _effective_candidates: list['_EffectiveRouteContext | _IncludedRouter'] = field(default_factory=list)
    _effective_candidates_version: int | None = None
    _effective_low_priority_routes: list['_EffectiveRouteContext'] = field(default_factory=list)
    _effective_low_priority_routes_version: int | None = None

    def effective_candidates(self) -> list['_EffectiveRouteContext | _IncludedRouter']:
        routes_version = self.original_router._get_routes_version()
        if routes_version == self._effective_candidates_version:
            return self._effective_candidates
        with self._effective_routes_lock:
            routes_version = self.original_router._get_routes_version()
            if routes_version == self._effective_candidates_version:
                return self._effective_candidates
            effective_candidates: list[_EffectiveRouteContext | _IncludedRouter] = []
            for route in self.original_router.routes:
                if isinstance(route, _IncludedRouter):
                    child_context = self.include_context.combine(route.include_context)
                    child_branch = _IncludedRouter(original_router=route.original_router, include_context=child_context)
                    effective_candidates.append(child_branch)
                    continue
                route_context = self._build_effective_context(route)
                if route_context is not None:
                    effective_candidates.append(route_context)
            self._effective_candidates = effective_candidates
            self._effective_candidates_version = routes_version
            return effective_candidates

    def effective_low_priority_routes(self) -> list['_EffectiveRouteContext']:
        routes_version = self.original_router._get_routes_version()
        if routes_version == self._effective_low_priority_routes_version:
            return self._effective_low_priority_routes
        with self._effective_routes_lock:
            routes_version = self.original_router._get_routes_version()
            if routes_version == self._effective_low_priority_routes_version:
                return self._effective_low_priority_routes
            effective_low_priority_routes: list[_EffectiveRouteContext] = []
            for route in self.original_router._low_priority_routes:
                route_context = self._build_effective_context(route)
                if route_context is not None:
                    if not isinstance(route, APIRoute):
                        effective_route = route_context.starlette_route or route
                        route_context.app = wrap_app_with_body_limit(effective_route.handle, self.include_context.max_body_size)
                    effective_low_priority_routes.append(route_context)
            for route in self.original_router.routes:
                if isinstance(route, _IncludedRouter):
                    child_context = self.include_context.combine(route.include_context)
                    child_branch = _IncludedRouter(original_router=route.original_router, include_context=child_context)
                    effective_low_priority_routes.extend(child_branch.effective_low_priority_routes())
            self._effective_low_priority_routes = effective_low_priority_routes
            self._effective_low_priority_routes_version = routes_version
            return effective_low_priority_routes

    def _build_effective_context(self, route: BaseRoute) -> _EffectiveRouteContext | None:
        if isinstance(route, APIRoute):
            return _EffectiveRouteContext.from_api_route(original_route=route, include_context=self.include_context)
        if isinstance(route, _FrontendRouteGroup):
            return _EffectiveRouteContext.from_frontend_route_group(original_route=route, include_context=self.include_context)
        if isinstance(route, routing.Route):
            starlette_route: BaseRoute = routing.Route(self.include_context.path_for(route), endpoint=route.endpoint, methods=list(route.methods or []), name=route.name, include_in_schema=route.include_in_schema)
            return _EffectiveRouteContext(original_route=route, starlette_route=starlette_route)
        if isinstance(route, APIWebSocketRoute):
            starlette_route = APIWebSocketRoute(self.include_context.path_for(route), endpoint=route.endpoint, name=route.name, dependencies=[*self.include_context.dependencies, *route.dependencies], dependency_overrides_provider=self.include_context.dependency_overrides_provider)
            return _EffectiveRouteContext(original_route=route, starlette_route=starlette_route)
        if isinstance(route, routing.WebSocketRoute):
            starlette_route = routing.WebSocketRoute(self.include_context.path_for(route), route.endpoint, name=route.name)
            return _EffectiveRouteContext(original_route=route, starlette_route=starlette_route)
        if isinstance(route, routing.Mount):
            starlette_route = copy.copy(route)
            starlette_route.path = self.include_context.path_for(route).rstrip('/')
            starlette_route.path_regex, starlette_route.path_format, starlette_route.param_convertors = compile_path(starlette_route.path + '/{path:path}')
            return _EffectiveRouteContext(original_route=route, starlette_route=starlette_route)
        if isinstance(route, routing.Host):
            if self.include_context.prefix:
                prefixed_app: ASGIApp = routing.Router(routes=[routing.Mount(self.include_context.prefix, app=route.app)])
            else:
                prefixed_app = route.app
            starlette_route = routing.Host(route.host, app=prefixed_app, name=route.name)
            return _EffectiveRouteContext(original_route=route, starlette_route=starlette_route)
        return None

    def _match(self, scope: Scope) -> tuple[Match, Scope, BaseRoute | None, _EffectiveRouteContext | None]:
        partial: tuple[Scope, BaseRoute, _EffectiveRouteContext | None] | None = None
        for candidate in self.effective_candidates():
            if isinstance(candidate, _IncludedRouter):
                match, child_scope = candidate.matches(scope)
                route: BaseRoute = candidate
                route_context = None
            elif isinstance(candidate.original_route, APIRoute):
                route_context = candidate
                fastapi_scope = _get_fastapi_scope(scope)
                previous_context = fastapi_scope.get(_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY, _SCOPE_MISSING)
                fastapi_scope[_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY] = route_context
                try:
                    match, child_scope = candidate.original_route.matches(scope)
                finally:
                    _restore_fastapi_scope_key(scope, _FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY, previous_context)
                route = candidate.original_route
            else:
                route_context = candidate
                match, child_scope = candidate.matches(scope)
                route = candidate.starlette_route or candidate.original_route
            if match == Match.FULL:
                return (match, child_scope, route, route_context)
            if match == Match.PARTIAL and partial is None:
                partial = (child_scope, route, route_context)
        if partial is not None:
            child_scope, route, route_context = partial
            return (Match.PARTIAL, child_scope, route, route_context)
        return (Match.NONE, {}, None, None)

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        fastapi_scope = _get_fastapi_scope(scope)
        previous_router = fastapi_scope.get(_FASTAPI_INCLUDED_ROUTER_KEY, _SCOPE_MISSING)
        fastapi_scope[_FASTAPI_INCLUDED_ROUTER_KEY] = self
        try:
            match, _ = self.original_router.matches(scope)
            return (match, {})
        finally:
            _restore_fastapi_scope_key(scope, _FASTAPI_INCLUDED_ROUTER_KEY, previous_router)

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        _apply_router_form_limits(scope, self.include_context.form_limits)
        _get_fastapi_scope(scope)[_FASTAPI_INCLUDED_ROUTER_KEY] = self
        await self.original_router.handle(scope, receive, send)

    async def _handle_selected(self, scope: Scope, receive: Receive, send: Send) -> None:
        match, child_scope, route, effective_context = self._match(scope)
        if match == Match.NONE or route is None:
            default = wrap_app_with_body_limit(self.original_router.default, self.include_context.max_body_size)
            await default(scope, receive, send)
            return
        _update_scope(scope, child_scope)
        if isinstance(route, _IncludedRouter):
            await route.handle(scope, receive, send)
            return
        if effective_context is not None:
            _route_selected(scope=scope, path=getattr(effective_context.starlette_route, 'path_format', None) or effective_context.path_format, mount=isinstance(route, routing.Mount))
            _get_fastapi_scope(scope)[_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY] = effective_context
            original_route = effective_context.original_route
            if isinstance(original_route, APIRoute):
                scope['route'] = original_route
                await original_route.handle(scope, receive, send)
                return
        handle = wrap_app_with_body_limit(route.handle, self.include_context.max_body_size)
        await handle(scope, receive, send)

    def effective_route_contexts(self) -> Iterator[_EffectiveRouteContext]:
        for candidate in self.effective_candidates():
            if isinstance(candidate, _IncludedRouter):
                yield from candidate.effective_route_contexts()
            else:
                yield candidate

    def url_path_for(self, name: str, /, **path_params: Any) -> Any:
        for route_context in self.effective_route_contexts():
            try:
                return route_context.url_path_for(name, **path_params)
            except routing.NoMatchFound:
                pass
        raise routing.NoMatchFound(name, path_params)

def _iter_included_route_candidates(routes: Sequence[BaseRoute]) -> Iterator[BaseRoute]:
    for route, route_context in _iter_routes_with_context(routes):
        if route_context is not None and route_context.starlette_route is not None:
            yield route_context.starlette_route
        else:
            yield route

def iter_route_contexts(routes: Sequence[BaseRoute | RouteContext]) -> Iterator[RouteContext]:
    for route in routes:
        if isinstance(route, RouteContext):
            yield route
            continue
        for original_route, route_context in _iter_routes_with_context([route]):
            if route_context is None:
                yield RouteContext(original_route)
            else:
                yield RouteContext(original_route, route_context)

def _iter_routes_with_context(routes: Sequence[BaseRoute]) -> Iterator[tuple[BaseRoute, _EffectiveRouteContext | None]]:
    for route in routes:
        if isinstance(route, _IncludedRouter):
            for route_context in route.effective_route_contexts():
                yield (route_context.original_route, route_context)
        else:
            yield (route, None)

def _normalize_frontend_path(path: str) -> str:
    if not path:
        raise AssertionError('A frontend path cannot be empty')
    if not path.startswith('/'):
        raise AssertionError("A frontend path must start with '/'")
    if path != '/':
        path = path.rstrip('/')
    return path

def _join_frontend_paths(prefix: str, path: str) -> str:
    if not prefix:
        return path
    if path == '/':
        return prefix
    return prefix + path

def _frontend_path_specificity(path: str) -> int:
    if path == '/':
        return 0
    return len(path)

def _get_resolved_absolute_path(path: str | os.PathLike[str]) -> str:
    return os.path.realpath(os.fspath(path))

def _resolve_frontend_check_dir(*, directory: str | os.PathLike[str], check_dir: bool | Literal['auto']) -> bool:
    if check_dir != 'auto':
        return check_dir
    if os.environ.get('FASTAPI_ENV') != 'development':
        return True
    if not os.path.isdir(directory):
        warnings.warn(f"Frontend directory '{directory}' does not exist. Resolved absolute path: '{_get_resolved_absolute_path(directory)}'", stacklevel=3)
    return False

class _FrontendStaticFiles(StaticFiles):

    def __init__(self, *, directory: str | os.PathLike[str], fallback: Literal['auto', 'index.html', '404.html'] | None, check_dir: bool) -> None:
        self.fallback = fallback
        if check_dir and (not os.path.isdir(directory)):
            raise RuntimeError(f"Frontend directory '{directory}' does not exist. Resolved absolute path: '{_get_resolved_absolute_path(directory)}'")
        super().__init__(directory=directory, html=True, check_dir=check_dir, follow_symlink=False)
        if check_dir and fallback in {'index.html', '404.html'}:
            self._check_fallback_file(fallback)

    def _check_fallback_file(self, fallback: str) -> None:
        _, stat_result = self.lookup_path(fallback)
        if stat_result is None or not stat.S_ISREG(stat_result.st_mode):
            raise RuntimeError(f"Frontend fallback file '{fallback}' does not exist in directory '{self.directory}'. Resolved absolute directory: '{self._get_resolved_directory()}'")

    def _get_resolved_directory(self) -> str:
        assert self.directory is not None
        return _get_resolved_absolute_path(self.directory)

    def get_path(self, scope: Scope) -> str:
        path = _get_fastapi_scope(scope).get(_FASTAPI_FRONTEND_PATH_KEY, '')
        assert isinstance(path, str)
        return os.path.normpath(os.path.join(*path.split('/')))

    async def get_response_for_scope(self, scope: Scope) -> Response:
        if not self.config_checked:
            await self.check_config()
            self.config_checked = True
        return await self.get_response(self.get_path(scope), scope)

    async def get_response(self, path: str, scope: Scope) -> Response:
        if scope['method'] not in ('GET', 'HEAD'):
            if await self._lookup_static_resource(path) is not None:
                raise HTTPException(status_code=405)
            raise HTTPException(status_code=404)
        static_resource = await self._lookup_static_resource(path)
        if static_resource is not None:
            full_path, stat_result, is_directory_index = static_resource
            if is_directory_index and (not scope['path'].endswith('/')):
                url = URL(scope=scope)
                url = url.replace(path=url.path + '/')
                return RedirectResponse(url=url)
            return self.file_response(full_path, stat_result, scope)
        if self.fallback == '404.html' or (self.fallback == 'auto' and await self._fallback_file_exists('404.html')):
            return await self._fallback_response('404.html', scope, status_code=404)
        if (self.fallback == 'index.html' or (self.fallback == 'auto' and await self._fallback_file_exists('index.html'))) and _is_frontend_navigation_request(scope):
            return await self._fallback_response('index.html', scope, status_code=200)
        raise HTTPException(status_code=404)

    async def _lookup_path(self, path: str) -> tuple[str, os.stat_result | None]:
        try:
            return await run_in_threadpool(self.lookup_path, path)
        except PermissionError:
            raise HTTPException(status_code=401) from None
        except OSError as exc:
            if exc.errno == errno.ENAMETOOLONG:
                raise HTTPException(status_code=404) from None
            raise exc
        except ValueError:
            raise HTTPException(status_code=404) from None

    async def _lookup_static_resource(self, path: str) -> tuple[str, os.stat_result, bool] | None:
        full_path, stat_result = await self._lookup_path(path)
        if stat_result is None:
            return None
        if stat.S_ISREG(stat_result.st_mode):
            return (full_path, stat_result, False)
        if stat.S_ISDIR(stat_result.st_mode):
            index_path = os.path.join(path, 'index.html')
            full_path, stat_result = await self._lookup_path(index_path)
            if stat_result is not None and stat.S_ISREG(stat_result.st_mode):
                return (full_path, stat_result, True)
        return None

    async def _fallback_file_exists(self, fallback: str) -> bool:
        _, stat_result = await run_in_threadpool(self.lookup_path, fallback)
        return stat_result is not None and stat.S_ISREG(stat_result.st_mode)

    async def _fallback_response(self, fallback: str, scope: Scope, *, status_code: int) -> Response:
        full_path, stat_result = await run_in_threadpool(self.lookup_path, fallback)
        if stat_result is None or not stat.S_ISREG(stat_result.st_mode):
            raise RuntimeError(f"Frontend fallback file '{fallback}' does not exist in directory '{self.directory}'. Resolved absolute directory: '{self._get_resolved_directory()}'")
        return self.file_response(full_path, stat_result, scope, status_code=status_code)

def _iter_accept_media_types(accept: str) -> Iterator[tuple[str, float]]:
    for raw_value in accept.split(','):
        message = email.message.Message()
        message['content-type'] = raw_value.strip()
        q = message.get_param('q')
        quality = 1.0
        if isinstance(q, str):
            try:
                quality = float(q)
            except ValueError:
                pass
        yield (f'{message.get_content_maintype()}/{message.get_content_subtype()}', quality)

def _is_frontend_navigation_request(scope: Scope) -> bool:
    request = Request(scope)
    for media_type, quality in _iter_accept_media_types(request.headers.get('accept', '')):
        if media_type in {'text/html', 'application/xhtml+xml'} and quality != 0:
            return True
    return False

class _FrontendRoute(BaseRoute):

    def __init__(self, path: str, *, directory: str | os.PathLike[str], fallback: Literal['auto', 'index.html', '404.html'] | None='auto', check_dir: bool) -> None:
        if fallback not in {'auto', 'index.html', '404.html', None}:
            raise AssertionError("fallback must be 'auto', 'index.html', '404.html', or None")
        self.path = _normalize_frontend_path(path)
        self.methods = {'GET', 'HEAD'}
        self.app = _FrontendStaticFiles(directory=directory, fallback=fallback, check_dir=check_dir)

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        return self.matches_with_path(scope, self.path)

    def matches_with_path(self, scope: Scope, path: str) -> tuple[Match, Scope]:
        if scope['type'] != 'http':
            return (Match.NONE, {})
        frontend_path = self._get_frontend_path(path, get_route_path(scope))
        if frontend_path is None:
            return (Match.NONE, {})
        child_scope = {_FASTAPI_SCOPE_KEY: {_FASTAPI_FRONTEND_PATH_KEY: frontend_path, _FASTAPI_FRONTEND_SPECIFICITY_KEY: _frontend_path_specificity(path)}}
        if scope['method'] not in self.methods:
            return (Match.PARTIAL, child_scope)
        return (Match.FULL, child_scope)

    def _get_frontend_path(self, path: str, route_path: str) -> str | None:
        if path == '/':
            return route_path.lstrip('/')
        if route_path == path:
            return ''
        prefix = path + '/'
        if route_path.startswith(prefix):
            return route_path[len(prefix):]
        return None

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        response = await self.app.get_response_for_scope(scope)
        await response(scope, receive, send)

    def url_path_for(self, name: str, /, **path_params: Any) -> URLPath:
        raise NoMatchFound(name, path_params)

class _FrontendRouteGroup(BaseRoute):

    def __init__(self, *, dependencies: Sequence[params.Depends] | None=None, dependency_overrides_provider: Any | None=None) -> None:
        self.routes: list[_FrontendRoute] = []
        self.dependencies = list(dependencies or [])
        self.dependency_overrides_provider = dependency_overrides_provider
        self.dependant, _, self._embed_body_fields = _build_dependant_with_parameterless_dependencies(path='', call=_frontend_dependency_endpoint, dependencies=self.dependencies)

    def add_frontend_route(self, path: str, *, directory: str | os.PathLike[str], fallback: Literal['auto', 'index.html', '404.html'] | None='auto', check_dir: bool) -> None:
        self.routes.append(_FrontendRoute(path, directory=directory, fallback=fallback, check_dir=check_dir))

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        match, child_scope, _ = self._match(scope, prefix='')
        return (match, child_scope)

    def matches_with_prefix(self, scope: Scope, prefix: str) -> tuple[Match, Scope]:
        match, child_scope, _ = self._match(scope, prefix=prefix)
        return (match, child_scope)

    def _match(self, scope: Scope, *, prefix: str) -> tuple[Match, Scope, _FrontendRoute | None]:
        full: tuple[Scope, _FrontendRoute, int] | None = None
        partial: tuple[Scope, _FrontendRoute, int] | None = None
        for route in self.routes:
            path = _join_frontend_paths(prefix, route.path)
            match, child_scope = route.matches_with_path(scope, path)
            specificity = _frontend_path_specificity(path)
            if match == Match.FULL:
                if full is None or specificity > full[2]:
                    full = (child_scope, route, specificity)
            elif match == Match.PARTIAL:
                if partial is None or specificity > partial[2]:
                    partial = (child_scope, route, specificity)
        if full is not None:
            child_scope, route, _ = full
            return (Match.FULL, child_scope, route)
        if partial is not None:
            child_scope, route, _ = partial
            return (Match.PARTIAL, child_scope, route)
        return (Match.NONE, {}, None)

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        effective_context = _get_scope_effective_route_context(scope)
        if isinstance(effective_context, _EffectiveRouteContext) and effective_context.original_route is self:
            prefix = effective_context.frontend_prefix
            dependant = effective_context.dependant
            dependency_overrides_provider = effective_context.dependency_overrides_provider
            embed_body_fields = effective_context._embed_body_fields
        else:
            prefix = ''
            dependant = self.dependant
            dependency_overrides_provider = self.dependency_overrides_provider
            embed_body_fields = self._embed_body_fields
        match, child_scope, route = self._match(scope, prefix=prefix)
        if match == Match.NONE or route is None:
            raise HTTPException(status_code=404)
        _update_scope(scope, child_scope)
        _route_selected(scope=scope, path=_join_frontend_paths(prefix, route.path).rstrip('/') + '/{path}')
        if match == Match.FULL and dependant and dependant.dependencies:
            async with self._solve_dependencies(scope, receive, send, dependant=dependant, dependency_overrides_provider=dependency_overrides_provider, embed_body_fields=embed_body_fields) as solved_result:
                response = await route.app.get_response_for_scope(scope)
                if response.background is None:
                    response.background = solved_result.background_tasks
                response.headers.raw.extend(solved_result.response.headers.raw)
                await response(scope, receive, send)
            return
        await route.handle(scope, receive, send)

    def url_path_for(self, name: str, /, **path_params: Any) -> URLPath:
        raise NoMatchFound(name, path_params)

    @asynccontextmanager
    async def _solve_dependencies(self, scope: Scope, receive: Receive, send: Send, *, dependant: Dependant, dependency_overrides_provider: Any | None, embed_body_fields: bool) -> AsyncIterator[SolvedDependency]:
        request = Request(scope, receive, send)
        previous_inner_astack = scope.get('fastapi_inner_astack', _SCOPE_MISSING)
        previous_function_astack = scope.get('fastapi_function_astack', _SCOPE_MISSING)
        try:
            async with AsyncExitStack() as request_stack:
                scope['fastapi_inner_astack'] = request_stack
                async with AsyncExitStack() as function_stack:
                    scope['fastapi_function_astack'] = function_stack
                    solved_result = await solve_dependencies(request=request, dependant=dependant, dependency_overrides_provider=dependency_overrides_provider, async_exit_stack=request_stack, embed_body_fields=embed_body_fields)
                    if solved_result.errors:
                        raise RequestValidationError(solved_result.errors)
                    yield solved_result
        finally:
            if previous_inner_astack is _SCOPE_MISSING:
                scope.pop('fastapi_inner_astack', None)
            else:
                scope['fastapi_inner_astack'] = previous_inner_astack
            if previous_function_astack is _SCOPE_MISSING:
                scope.pop('fastapi_function_astack', None)
            else:
                scope['fastapi_function_astack'] = previous_function_astack

class APIRouter(routing.Router):
    """
    `APIRouter` class, used to group *path operations*, for example to structure
    an app in multiple files. It would then be included in the `FastAPI` app, or
    in another `APIRouter` (ultimately included in the app).

    Read more about it in the
    [FastAPI docs for Bigger Applications - Multiple Files](https://fastapi.tiangolo.com/tutorial/bigger-applications/).

    ## Example

    ```python
    from fastapi import APIRouter, FastAPI

    app = FastAPI()
    router = APIRouter()


    @router.get("/users/", tags=["users"])
    async def read_users():
        return [{"username": "Rick"}, {"username": "Morty"}]


    app.include_router(router)
    ```
    """

    def __init__(self, *, prefix: Annotated[str, Doc('An optional path prefix for the router.')]='', tags: Annotated[list[str | Enum] | None, Doc('\n                A list of tags to be applied to all the *path operations* in this\n                router.\n\n                It will be added to the generated OpenAPI (e.g. visible at `/docs`).\n\n                Read more about it in the\n                [FastAPI docs for Path Operation Configuration](https://fastapi.tiangolo.com/tutorial/path-operation-configuration/).\n                ')]=None, dependencies: Annotated[Sequence[params.Depends] | None, Doc('\n                A list of dependencies (using `Depends()`) to be applied to all the\n                *path operations* in this router.\n\n                Read more about it in the\n                [FastAPI docs for Bigger Applications - Multiple Files](https://fastapi.tiangolo.com/tutorial/bigger-applications/#include-an-apirouter-with-a-custom-prefix-tags-responses-and-dependencies).\n                ')]=None, default_response_class: Annotated[type[Response], Doc('\n                The default response class to be used.\n\n                Read more in the\n                [FastAPI docs for Custom Response - HTML, Stream, File, others](https://fastapi.tiangolo.com/advanced/custom-response/#default-response-class).\n                ')]=Default(JSONResponse), responses: Annotated[dict[int | str, dict[str, Any]] | None, Doc('\n                Additional responses to be shown in OpenAPI.\n\n                It will be added to the generated OpenAPI (e.g. visible at `/docs`).\n\n                Read more about it in the\n                [FastAPI docs for Additional Responses in OpenAPI](https://fastapi.tiangolo.com/advanced/additional-responses/).\n\n                And in the\n                [FastAPI docs for Bigger Applications](https://fastapi.tiangolo.com/tutorial/bigger-applications/#include-an-apirouter-with-a-custom-prefix-tags-responses-and-dependencies).\n                ')]=None, callbacks: Annotated[list[BaseRoute] | None, Doc('\n                OpenAPI callbacks that should apply to all *path operations* in this\n                router.\n\n                It will be added to the generated OpenAPI (e.g. visible at `/docs`).\n\n                Read more about it in the\n                [FastAPI docs for OpenAPI Callbacks](https://fastapi.tiangolo.com/advanced/openapi-callbacks/).\n                ')]=None, routes: Annotated[list[BaseRoute] | None, Doc("\n                **Note**: you probably shouldn't use this parameter, it is inherited\n                from Starlette and supported for compatibility.\n\n                ---\n\n                A list of routes to serve incoming HTTP and WebSocket requests.\n                "), deprecated("\n                You normally wouldn't use this parameter with FastAPI, it is inherited\n                from Starlette and supported for compatibility.\n\n                In FastAPI, you normally would use the *path operation methods*,\n                like `router.get()`, `router.post()`, etc.\n                ")]=None, redirect_slashes: Annotated[bool, Doc("\n                Whether to detect and redirect slashes in URLs when the client doesn't\n                use the same format.\n                ")]=True, default: Annotated[ASGIApp | None, Doc('\n                Default function handler for this router. Used to handle\n                404 Not Found errors.\n                ')]=None, dependency_overrides_provider: Annotated[Any | None, Doc("\n                Only used internally by FastAPI to handle dependency overrides.\n\n                You shouldn't need to use it. It normally points to the `FastAPI` app\n                object.\n                ")]=None, route_class: Annotated[type[APIRoute], Doc('\n                Custom route (*path operation*) class to be used by this router.\n\n                Read more about it in the\n                [FastAPI docs for Custom Request and APIRoute class](https://fastapi.tiangolo.com/how-to/custom-request-and-route/#custom-apiroute-class-in-a-router).\n                ')]=APIRoute, on_startup: Annotated[Sequence[Callable[[], Any]] | None, Doc('\n                A list of startup event handler functions.\n\n                You should instead use the `lifespan` handlers.\n\n                Read more in the [FastAPI docs for `lifespan`](https://fastapi.tiangolo.com/advanced/events/).\n                ')]=None, on_shutdown: Annotated[Sequence[Callable[[], Any]] | None, Doc('\n                A list of shutdown event handler functions.\n\n                You should instead use the `lifespan` handlers.\n\n                Read more in the\n                [FastAPI docs for `lifespan`](https://fastapi.tiangolo.com/advanced/events/).\n                ')]=None, lifespan: Annotated[Lifespan[Any] | None, Doc('\n                A `Lifespan` context manager handler. This replaces `startup` and\n                `shutdown` functions with a single context manager.\n\n                Read more in the\n                [FastAPI docs for `lifespan`](https://fastapi.tiangolo.com/advanced/events/).\n                ')]=None, deprecated: Annotated[bool | None, Doc('\n                Mark all *path operations* in this router as deprecated.\n\n                It will be added to the generated OpenAPI (e.g. visible at `/docs`).\n\n                Read more about it in the\n                [FastAPI docs for Path Operation Configuration](https://fastapi.tiangolo.com/tutorial/path-operation-configuration/).\n                ')]=None, include_in_schema: Annotated[bool, Doc('\n                To include (or not) all the *path operations* in this router in the\n                generated OpenAPI.\n\n                This affects the generated OpenAPI (e.g. visible at `/docs`).\n\n                Read more about it in the\n                [FastAPI docs for Query Parameters and String Validations](https://fastapi.tiangolo.com/tutorial/query-params-str-validations/#exclude-parameters-from-openapi).\n                ')]=True, generate_unique_id_function: Annotated[Callable[[APIRoute], str], Doc('\n                Customize the function used to generate unique IDs for the *path\n                operations* shown in the generated OpenAPI.\n\n                This is particularly useful when automatically generating clients or\n                SDKs for your API.\n\n                Read more about it in the\n                [FastAPI docs about how to Generate Clients](https://fastapi.tiangolo.com/advanced/generate-clients/#custom-generate-unique-id-function).\n                ')]=Default(generate_unique_id), strict_content_type: Annotated[bool, Doc("\n                Enable strict checking for request Content-Type headers.\n\n                When `True` (the default), requests with a body that do not include\n                a `Content-Type` header will **not** be parsed as JSON.\n\n                This prevents potential cross-site request forgery (CSRF) attacks\n                that exploit the browser's ability to send requests without a\n                Content-Type header, bypassing CORS preflight checks. In particular\n                applicable for apps that need to be run locally (in localhost).\n\n                When `False`, requests without a `Content-Type` header will have\n                their body parsed as JSON, which maintains compatibility with\n                certain clients that don't send `Content-Type` headers.\n\n                Read more about it in the\n                [FastAPI docs for Strict Content-Type](https://fastapi.tiangolo.com/advanced/strict-content-type/).\n                ")]=Default(True), max_body_size: Annotated[int | None, Doc('\n                Maximum total HTTP request body size in bytes, including files and\n                multipart overhead.\n\n                A more specific configured limit overrides the enclosing default.\n                `None` inherits that default, or leaves the body unlimited when no\n                limit is configured. `0` allows only an empty body.\n\n                Read more in the\n                [FastAPI docs for Request Body Limits](https://fastapi.tiangolo.com/advanced/request-body-limits/).\n                ')]=None, form_limits: Annotated[_FormLimits | None, Doc('Limits for automatic form parsing. Set field and file counts with `max_fields` and `max_files`, or the size of a text field in bytes with `max_part_size`. Each omitted setting inherits its default.')]=None) -> None:
        validate_max_body_size(max_body_size)
        if lifespan is None:
            lifespan_context: Lifespan[Any] = _DefaultLifespan(self)
        elif inspect.isasyncgenfunction(lifespan):
            lifespan_context = asynccontextmanager(lifespan)
        elif inspect.isgeneratorfunction(lifespan):
            lifespan_context = _wrap_gen_lifespan_context(lifespan)
        else:
            lifespan_context = lifespan
        self.lifespan_context = lifespan_context
        super().__init__(routes=routes, redirect_slashes=redirect_slashes, default=default, lifespan=lifespan_context, middleware=[Middleware(wrap_app_with_body_limit, max_body_size=max_body_size)] if max_body_size is not None else None)
        if prefix:
            assert prefix.startswith('/'), "A path prefix must start with '/'"
            assert not prefix.endswith('/'), "A path prefix must not end with '/', as the routes will start with '/'"
        self.on_startup: list[Callable[[], Any]] = [] if on_startup is None else list(on_startup)
        self.on_shutdown: list[Callable[[], Any]] = [] if on_shutdown is None else list(on_shutdown)
        self.prefix = prefix
        self.tags: list[str | Enum] = tags or []
        self.dependencies = list(dependencies or [])
        self.deprecated = deprecated
        self.include_in_schema = include_in_schema
        self.responses = responses or {}
        self.callbacks = callbacks or []
        self.dependency_overrides_provider = dependency_overrides_provider
        self.route_class = route_class
        self.default_response_class = default_response_class
        self.generate_unique_id_function = generate_unique_id_function
        self.form_limits = _validate_form_limits(form_limits)
        self.strict_content_type = strict_content_type
        self.max_body_size = max_body_size
        self._routes_version = 0
        self._low_priority_routes: list[BaseRoute] = []
        self._frontend_routes: _FrontendRouteGroup | None = None

    def _mark_routes_changed(self) -> None:
        self._routes_version += 1

    def _get_routes_version(self, seen: set[int] | None=None) -> int:
        if seen is None:
            seen = set()
        router_id = id(self)
        if router_id in seen:
            return self._routes_version
        seen.add(router_id)
        version = self._routes_version
        for route in self.routes:
            if isinstance(route, _IncludedRouter):
                version += route.original_router._get_routes_version(seen)
        return version

    def _contains_router(self, router: 'APIRouter', seen: set[int] | None=None) -> bool:
        if seen is None:
            seen = set()
        router_id = id(self)
        if router_id in seen:
            return False
        seen.add(router_id)
        for route in self.routes:
            if not isinstance(route, _IncludedRouter):
                continue
            if route.original_router is router:
                return True
            if route.original_router._contains_router(router, seen):
                return True
        return False

    def add_route(self, path: str, endpoint: Callable[[Request], Awaitable[Response] | Response], methods: Collection[str] | None=None, name: str | None=None, include_in_schema: bool=True) -> None:
        super().add_route(path, endpoint, methods=methods, name=name, include_in_schema=include_in_schema)
        self._mark_routes_changed()

    def add_websocket_route(self, path: str, endpoint: Callable[[WebSocket], Awaitable[None]], name: str | None=None) -> None:
        super().add_websocket_route(path, endpoint, name=name)
        self._mark_routes_changed()

    def frontend(self, path: Annotated[str, Doc('\n                The URL path prefix where the frontend build should be served.\n                ')], *, directory: Annotated[str | os.PathLike[str], Doc('\n                The directory containing the static frontend build output.\n                ')], fallback: Annotated[Literal['auto', 'index.html', '404.html'] | None, Doc('\n                The fallback file behavior for missing frontend paths.\n                ')]='auto', check_dir: Annotated[bool | Literal['auto'], Doc('\n                Check that the frontend directory exists when the app is created. When\n                set to `"auto"`, skip the check with a warning when `FASTAPI_ENV` is\n                `"development"`, and check it otherwise. The `fastapi dev` command\n                sets `FASTAPI_ENV` to `"development"` if it is not already set.\n                ')]='auto') -> None:
        """
        Serve a static frontend build as low-priority routes.

        Use this for frontend tools that build static files into a directory,
        such as `dist`. **FastAPI** path operations are checked first, and
        the frontend files are checked only if no normal route matched.

        A typical project could look like this:

        ```text
        .
        ├── pyproject.toml
        ├── app
        │   ├── __init__.py
        │   └── main.py
        └── dist
            ├── index.html
            └── assets
                └── app.js
        ```

        Then in `app/main.py`:

        ```python
        from fastapi import APIRouter, FastAPI

        app = FastAPI()
        router = APIRouter()
        router.frontend("/", directory="dist")
        app.include_router(router)
        ```
        """
        check_dir = _resolve_frontend_check_dir(directory=directory, check_dir=check_dir)
        normalized_path = _normalize_frontend_path(path)
        if self._frontend_routes is None:
            self._frontend_routes = _FrontendRouteGroup(dependencies=self.dependencies, dependency_overrides_provider=self.dependency_overrides_provider)
            self._low_priority_routes.append(self._frontend_routes)
        self._frontend_routes.add_frontend_route(_join_frontend_paths(self.prefix, normalized_path), directory=directory, fallback=fallback, check_dir=check_dir)
        self._mark_routes_changed()

    async def app(self, scope: Scope, receive: Receive, send: Send) -> None:
        assert scope['type'] in ('http', 'websocket', 'lifespan')
        _apply_router_form_limits(scope, self.form_limits)
        if 'router' not in scope:
            scope['router'] = self
        if scope['type'] == 'lifespan':
            await self.lifespan(scope, receive, send)
            return
        partial: tuple[BaseRoute, Scope] | None = None
        for route in self.routes:
            match, child_scope = route.matches(scope)
            if match == Match.FULL:
                _update_scope(scope, child_scope)
                _route_selected(scope=scope, path=getattr(route, 'path_format', None), mount=isinstance(route, routing.Mount))
                await route.handle(scope, receive, send)
                return
            if match == Match.PARTIAL and partial is None:
                partial = (route, child_scope)
        if partial is not None:
            route, child_scope = partial
            _update_scope(scope, child_scope)
            _route_selected(scope=scope, path=getattr(route, 'path_format', None), mount=isinstance(route, routing.Mount))
            await route.handle(scope, receive, send)
            return
        route_path = get_route_path(scope)
        if scope['type'] == 'http' and self.redirect_slashes and (route_path != '/'):
            redirect_scope = dict(scope)
            if route_path.endswith('/'):
                redirect_scope['path'] = redirect_scope['path'].rstrip('/')
            else:
                redirect_scope['path'] = redirect_scope['path'] + '/'
            for route in self.routes:
                match, _ = route.matches(redirect_scope)
                if match != Match.NONE:
                    if scope.get('fastapi.telemetry') is not None:
                        telemetry_route: BaseRoute | _EffectiveRouteContext | None = route
                        while isinstance(telemetry_route, _IncludedRouter):
                            _, _, matched_route, matched_context = telemetry_route._match(redirect_scope)
                            telemetry_route = matched_context.starlette_route or matched_context if matched_context is not None else matched_route
                        _route_selected(scope=scope, path=getattr(telemetry_route, 'path_format', None))
                    redirect_url = URL(scope=redirect_scope)
                    response = RedirectResponse(url=str(redirect_url))
                    await response(scope, receive, send)
                    return
        low_priority_match, low_priority_scope, low_priority_route, low_priority_context = self._match_low_priority(scope)
        if low_priority_match != Match.NONE and low_priority_route is not None:
            _update_scope(scope, low_priority_scope)
            _route_selected(scope=scope, path=getattr(low_priority_context or low_priority_route, 'path_format', None))
            if low_priority_context is not None:
                _get_fastapi_scope(scope)[_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY] = low_priority_context
                original_route = low_priority_context.original_route
                if isinstance(original_route, APIRoute):
                    scope['route'] = original_route
                    await original_route.handle(scope, receive, send)
                    return
                assert low_priority_context.app is not None
                await low_priority_context.app(scope, receive, send)
            else:
                await low_priority_route.handle(scope, receive, send)
            return
        await self.default(scope, receive, send)

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        included_router = _get_scope_included_router(scope)
        if isinstance(included_router, _IncludedRouter) and included_router.original_router is self:
            await included_router._handle_selected(scope, receive, send)
            return
        await self.app(scope, receive, send)

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        included_router = _get_scope_included_router(scope)
        if isinstance(included_router, _IncludedRouter) and included_router.original_router is self:
            match, child_scope, _, _ = included_router._match(scope)
            return (match, child_scope)
        return (Match.NONE, {})

    def _iter_low_priority_routes(self) -> Iterator[BaseRoute | _EffectiveRouteContext]:
        yield from self._low_priority_routes
        for route in self.routes:
            if isinstance(route, _IncludedRouter):
                yield from route.effective_low_priority_routes()

    def _match_low_priority(self, scope: Scope) -> tuple[Match, Scope, BaseRoute | None, _EffectiveRouteContext | None]:
        full: tuple[Scope, BaseRoute, _EffectiveRouteContext | None] | None = None
        partial: tuple[Scope, BaseRoute, _EffectiveRouteContext | None] | None = None
        for candidate in self._iter_low_priority_routes():
            route: BaseRoute
            if isinstance(candidate, _EffectiveRouteContext):
                route_context: _EffectiveRouteContext | None = candidate
                original_route = candidate.original_route
                if isinstance(original_route, APIRoute):
                    fastapi_scope = _get_fastapi_scope(scope)
                    previous_context = fastapi_scope.get(_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY, _SCOPE_MISSING)
                    fastapi_scope[_FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY] = route_context
                    try:
                        match, child_scope = original_route.matches(scope)
                    finally:
                        _restore_fastapi_scope_key(scope, _FASTAPI_EFFECTIVE_ROUTE_CONTEXT_KEY, previous_context)
                    route = original_route
                else:
                    match, child_scope = candidate.matches(scope)
                    route = candidate.starlette_route or original_route
            else:
                route_context = None
                match, child_scope = candidate.matches(scope)
                route = candidate
            if match == Match.FULL:
                if full is None or self._frontend_match_is_more_specific(child_scope, full[0]):
                    full = (child_scope, route, route_context)
            elif match == Match.PARTIAL:
                if partial is None or self._frontend_match_is_more_specific(child_scope, partial[0]):
                    partial = (child_scope, route, route_context)
        if full is not None:
            child_scope, route, route_context = full
            return (Match.FULL, child_scope, route, route_context)
        if partial is not None:
            child_scope, route, route_context = partial
            return (Match.PARTIAL, child_scope, route, route_context)
        return (Match.NONE, {}, None, None)

    def _frontend_match_is_more_specific(self, child_scope: Scope, previous_child_scope: Scope) -> bool:
        specificity = _frontend_scope_specificity(child_scope)
        previous_specificity = _frontend_scope_specificity(previous_child_scope)
        if specificity is None or previous_specificity is None:
            return False
        return specificity > previous_specificity

